// Device icons are Material Design Icons (subset generated by scripts/gen-icons.mjs).
// In Home Assistant they are previewed with <ha-icon icon="mdi:...">.
import { DEVICE_ICONS, LEGACY_ICONS } from "./icon-list";

export { DEVICE_ICONS, LEGACY_ICONS };

/** Normalise legacy (v0.1 LVGL symbol) names to the MDI name used by the device. */
export function normalizeIcon(key: string | null): string | null {
  if (!key) return null;
  return LEGACY_ICONS[key] ?? key;
}

export function iconMdi(key: string): string {
  return `mdi:${normalizeIcon(key)}`;
}

/** Short fallback text when <ha-icon> is not available (standalone dev harness). */
export function iconFallback(key: string): string {
  const n = normalizeIcon(key) ?? "";
  return n
    .split("-")
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase() ?? "")
    .join("");
}
